"""Host JVM qualification and outbox contract; Android APIs are instrumented stubs."""
from pathlib import Path
import tempfile, subprocess
root=Path(__file__).resolve().parents[1]
source=root/'tools/packager/android/app/src/main/java/org/cachymusic/app'
stubs={
'android/content/SharedPreferences.java':'''package android.content; import java.util.Map; public interface SharedPreferences {String getString(String k,String d); boolean getBoolean(String k,boolean d); boolean contains(String k); Map<String,?> getAll(); Editor edit(); interface Editor{Editor clear();Editor remove(String k);Editor putString(String k,String v);Editor putBoolean(String k,boolean v);boolean commit();}}''',
'android/content/Context.java':'''package android.content; import java.util.*; public class Context{public static final int MODE_PRIVATE=0;public boolean fail=false;private final Map<String,Object> data=new HashMap<>();public SharedPreferences getSharedPreferences(String n,int mode){return new SharedPreferences(){public String getString(String k,String d){return (String)data.getOrDefault(k,d);}public boolean getBoolean(String k,boolean d){return (Boolean)data.getOrDefault(k,d);}public boolean contains(String k){return data.containsKey(k);}public Map<String,?> getAll(){return new HashMap<>(data);}public Editor edit(){return new Editor(){Map<String,Object> puts=new HashMap<>();Set<String> removes=new HashSet<>();boolean clear=false;public Editor clear(){clear=true;return this;}public Editor remove(String k){removes.add(k);return this;}public Editor putString(String k,String v){puts.put(k,v);return this;}public Editor putBoolean(String k,boolean v){puts.put(k,v);return this;}public boolean commit(){if(fail)return false;if(clear)data.clear();for(String k:removes)data.remove(k);data.putAll(puts);return true;}};}};}}''',
'org/json/JSONObject.java':'''package org.json; import java.util.*; public class JSONObject {final Map<String,Object> values=new LinkedHashMap<>();String raw;public JSONObject(){}public JSONObject(String s){if(s.equals("corrupt"))throw new IllegalArgumentException("bad JSON");raw=s;}public JSONObject put(String k,Object v){values.put(k,v);return this;}public String toString(){return raw==null?values.toString():raw;}}''',
'org/json/JSONArray.java':'''package org.json; import java.util.*; public class JSONArray {final List<Object> values=new ArrayList<>();public JSONArray put(Object v){values.add(v);return this;}public int length(){return values.size();}public String toString(){return values.toString();}}''',
'org/cachymusic/app/NativeListeningTest.java':'''package org.cachymusic.app; import android.content.Context; public class NativeListeningTest {static void chk(boolean b,String m){if(!b)throw new AssertionError(m);}public static void main(String[] args){NativeListeningCounter c=new NativeListeningCounter();c.begin();for(int i=0;i<30;i++)chk(!c.sample(i*1000,i*1000,90000,true),"early");chk(c.sample(30000,30000,90000,true),"qualified");c.committed();chk(!c.sample(31000,31000,90000,true),"duplicate");c.begin();c.sample(0,0,90000,true);c.sample(1000,50000,90000,true);c.interrupt();chk(!c.sample(30000,79000,90000,true),"seek and suspend");c.begin();for(int i=0;i<5;i++)chk(!c.sample(i*1000,i*1000,10000,true),"short early");chk(c.sample(5000,5000,10000,true),"short qualified");
Context ctx=new Context();chk(NativeListeningJournal.generation(ctx)==null,"default off");chk(NativeListeningJournal.configure(ctx,true,"0",false),"configure");chk(NativeListeningJournal.append(ctx,"0","native-one","content://song","Track","Artist","Album",10000),"append");chk(NativeListeningJournal.append(ctx,"0","native-one","content://song","Track","Artist","Album",10000),"idempotent");chk(NativeListeningJournal.pending(ctx).contains("native-one"),"pending");chk(!NativeListeningJournal.acknowledge(ctx,"native-one","1"),"wrong generation ack");chk(NativeListeningJournal.configure(ctx,false,"0",false),"optout");chk(!NativeListeningJournal.append(ctx,"0","native-two","content://song","Track","Artist","Album",10000),"disabled write");chk(NativeListeningJournal.pending(ctx).contains("native-one"),"optout preserves history");chk(NativeListeningJournal.configure(ctx,true,"1",false),"new generation");chk(NativeListeningJournal.pending(ctx).equals("[]"),"clear old receipts");chk(!NativeListeningJournal.configure(ctx,true,"0",false),"reject stale config");chk(NativeListeningJournal.configure(ctx,false,"0",false),"stale privacy stop");chk(NativeListeningJournal.generation(ctx)==null,"stale stop disables");chk(!NativeListeningJournal.configure(ctx,false,"0",true),"reject stale erase");chk(NativeListeningJournal.configure(ctx,true,"1",false),"resume current generation");ctx.fail=true;chk(!NativeListeningJournal.configure(ctx,false,"1",false),"privacy commit fails");chk(NativeListeningJournal.generation(ctx)==null,"failed privacy commit fails closed in process");ctx.fail=false;chk(NativeListeningJournal.configure(ctx,true,"1",false),"confirmed resume");ctx.getSharedPreferences("cachymusic_native_listening",0).edit().putString("visit:malformed","corrupt").commit();chk(NativeListeningJournal.append(ctx,"1","native-valid","content://song","Track","Artist","Album",10000),"valid behind malformed");chk(NativeListeningJournal.pending(ctx).contains("native-valid"),"malformed did not poison batch");chk(NativeListeningJournal.acknowledge(ctx,"native-valid","1"),"valid ack");ctx.getSharedPreferences("cachymusic_native_listening",0).edit().remove("visit:malformed").commit();chk(!NativeListeningJournal.append(ctx,"0","native-old","content://song","Track","Artist","Album",10000),"reject stale event");ctx.fail=true;chk(!NativeListeningJournal.append(ctx,"1","native-failed","content://song","Track","Artist","Album",10000),"disk failure");ctx.fail=false;chk(NativeListeningJournal.append(ctx,"1","native-ok","content://song","Track","Artist","Album",10000),"retry");chk(NativeListeningJournal.acknowledge(ctx,"native-ok","1"),"ack");chk(NativeListeningJournal.pending(ctx).equals("[]"),"ack removed");// Simulate 70 valid JSON receipts which cannot be acknowledged. Three calls must offer every receipt without deletion.
for(int i=0;i<70;i++)chk(NativeListeningJournal.append(ctx,"1",String.format("native-batch-%03d",i),"content://song","Track","Artist","Album",10000),"batch insert");
String offered=NativeListeningJournal.pending(ctx)+NativeListeningJournal.pending(ctx)+NativeListeningJournal.pending(ctx);
for(int i=0;i<70;i++)chk(offered.contains(String.format("native-batch-%03d",i)),"starved receipt "+i);
chk(NativeListeningJournal.configure(ctx,false,"1",true),"erase");chk(NativeListeningJournal.generation(ctx)==null,"erase disables");System.out.println("PASS native qualification, opt-out, generation, receipt contract and acknowledgement (host stubs)");}}'''
}
with tempfile.TemporaryDirectory() as tmp:
 d=Path(tmp);files=[]
 for name,body in stubs.items():
  p=d/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body);files.append(str(p))
 subprocess.run(['javac','--release','17','-d',str(d),str(source/'NativeListeningCounter.java'),str(source/'NativeListeningJournal.java'),*files],check=True,timeout=30)
 subprocess.run(['java','-cp',str(d),'org.cachymusic.app.NativeListeningTest'],check=True,timeout=20)
